"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["31984"],{45071(e){e.exports=JSON.parse('{"id":"V4-210","slug":"alternative-credit-scoring","term":"Alternative Credit Scoring","also_known_as":[],"difficulty":"Intermediate","definition":"Alternative credit scoring is the use of non-traditional data, such as rent and utility payments, mobile phone usage, bank account transactions and other digital information, to assess a person\u2019s or business\u2019s creditworthiness.","explanation":["Traditional credit scores rely mainly on credit history, such as past loans and credit cards. People with little or no credit history, sometimes called credit invisible or thin-file, such as young adults, recent immigrants and people in countries with limited credit bureaus, often struggle to borrow even if they would repay reliably.","Alternative credit scoring uses other data to fill this gap. Examples include rent, utility and phone bill payments; bank account cash flow data, often accessed with the customer\u2019s permission through open banking; and, in some markets, mobile money and e-commerce activity.","For example, a lender might approve a loan for a young person with no credit history after analysing a year of their bank transactions, showing regular income and on-time rent payments.","Alternative credit scoring can expand access to credit and improve risk assessment. However, it raises concerns about privacy, transparency and fairness. Some data may reflect or reinforce existing biases, and complex models can make it hard to explain why someone was rejected. Regulators require lenders to follow fair lending, data protection and consumer protection laws when using alternative data."],"note":"","total":1725,"prev":{"slug":"alpha","term":"Alpha"},"next":{"slug":"alternative-data","term":"Alternative Data"}}')}}]);